#!/bin/bash
# set-dark-background.sh - the GTK "dark application background" role (Knomadic: GTK Colors / Titlebars > Dark Application Background):
# the libadwaita view/card/dialog/headerbar tokens that share one near-black value, replaced everywhere that hex appears in the GTK3/GTK4 files below.
# The current value is detected from the real tokens (never a hardcoded literal), so it is safe to re-run.
#
# SCOPE (narrowed 2026-10-17): GTK only. It no longer touches kdeglobals / bluegrey.colors (generated by fm-tweaks from the Thunar swatches), the
# catppuccin GtkSourceView styles (Text Editor has its own scripts) or backups. It never owned the Qt titlebar (set-qt-titlebar-color.sh) or any
# per-app swatch.
#
# Usage: ./set-dark-background.sh <new-hex-color>
#        ./set-dark-background.sh --get   (print current GTK-side hex)

set -euo pipefail

GTK4_CSS="$HOME/.config/gtk-4.0/gtk.css"

get_current_gtk() {
    local tok v
    for tok in view_bg_color card_bg_color dialog_bg_color headerbar_bg_color; do
        v=$(grep -oP "(?<=@define-color ${tok} #)[0-9a-fA-F]{6}" "$GTK4_CSS" 2>/dev/null | head -1 || true)
        if [ -n "$v" ]; then
            echo "$v"
            return 0
        fi
    done
}

if [ "${1:-}" == "--get" ]; then
    get_current_gtk
    exit 0
fi

if [ $# -ne 1 ]; then
    echo "Usage: $0 <new-hex-color>"
    exit 1
fi

NEW_HEX="${1#\#}"
NEW_HEX="${NEW_HEX,,}"

if ! [[ "$NEW_HEX" =~ ^[0-9a-f]{6}$ ]]; then
    echo "Error: '$1' doesn't look like a valid 6-digit hex color."
    exit 1
fi

if [ ! -f "$GTK4_CSS" ]; then
    echo "Error: $GTK4_CSS not found - can't detect current color."
    exit 1
fi

OLD_HEX=$(get_current_gtk)
OLD_HEX="${OLD_HEX,,}"

if [ -z "$OLD_HEX" ]; then
    echo "Error: couldn't find a current dark-background hex in $GTK4_CSS"
    exit 1
fi

if [ "$OLD_HEX" == "$NEW_HEX" ]; then
    echo "GTK side already #$NEW_HEX - nothing to do."
    exit 0
fi

echo "GTK dark background: #$OLD_HEX -> #$NEW_HEX"
echo

HEX_FILES=(
    "$GTK4_CSS"
    "$HOME/.config/gtk-3.0/gtk.css"
    "$HOME/.themes/adw-gtk3-dark/gtk-3.0/gtk.css"
    "$HOME/.themes/adw-gtk3-dark/gtk-3.0/gtk-dark.css"
    "$HOME/.themes/adw-gtk3-dark/gtk-4.0/gtk.css"
    "$HOME/.themes/adw-gtk3-dark/gtk-4.0/gtk-dark.css"
)

for f in "${HEX_FILES[@]}"; do
    if [ -f "$f" ]; then
        python3 "$HOME/.themes/machine-setup/replace_color_skip_fg.py" hex "$f" "$OLD_HEX" "$NEW_HEX"
        echo "  hex updated: $f"
    fi
done

echo
echo "Done. Restart GTK apps to see the change - some may glitch on a live config swap, just reopen them."
